import{_ as t,o as d,c as a,a2 as o}from"./chunks/framework.Cd7mb1YL.js";const p=JSON.parse('{"title":"API","description":"Every component, type and function the package exports, one page each: what it is, what it takes and what it gives back.","frontmatter":{"title":"API","order":2},"headers":[],"relativePath":"api/index.md","filePath":"en/api/index.md","lastUpdated":1789199647000}'),r={name:"api/index.md"};function c(i,e,n,s,h,y){return d(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="api" tabindex="-1">API <a class="header-anchor" href="#api" aria-label="Permalink to &quot;API&quot;">​</a></h1><p>Every component, type and function the package exports, one page each: what it is, what it takes and what it gives back.</p><p>Everything here exists and runs in whichever package the switch above the menu is set to. Where only one of the two has a name, the page says so and points at what the other one does instead.</p><h2 id="components" tabindex="-1">Components <a class="header-anchor" href="#components" aria-label="Permalink to &quot;Components&quot;">​</a></h2><div class="mawy-fw" data-fw="react"><table tabindex="0"><thead><tr><th>Page</th><th>What it is</th></tr></thead><tbody><tr><td><a href="./components/mawy-viewer"><code>MawyViewer</code></a></td><td>A Markdown document, rendered and not editable.</td></tr><tr><td><a href="./components/mawy-editor"><code>MawyEditor</code></a></td><td>A Markdown editor with the viewer beside it.</td></tr><tr><td><a href="./components/mawy-document"><code>MawyDocument</code></a></td><td>A document drawn on a server, with no JavaScript shipped for it.</td></tr></tbody></table></div><div class="mawy-fw" data-fw="flutter"><table tabindex="0"><thead><tr><th>Page</th><th>What it is</th></tr></thead><tbody><tr><td><a href="./components/mawy-viewer"><code>MawyViewer</code></a></td><td>A Markdown document, rendered and not editable.</td></tr><tr><td><a href="./components/mawy-editor"><code>MawyEditor</code></a></td><td>A Markdown editor with the viewer beside it.</td></tr></tbody></table></div><h2 id="types" tabindex="-1">Types <a class="header-anchor" href="#types" aria-label="Permalink to &quot;Types&quot;">​</a></h2><div class="mawy-fw" data-fw="react"><table tabindex="0"><thead><tr><th>Page</th><th>What it covers</th></tr></thead><tbody><tr><td><a href="./types/editor-mode">Editor modes</a></td><td><code>MawyMode</code></td></tr><tr><td><a href="./types/editor-toolbar-item"><code>MawyEditorToolbarItem</code></a></td><td><code>MawyEditorToolbarItem</code>, <code>MawyEditorToolbarOption</code></td></tr><tr><td><a href="./types/editor-status-item"><code>MawyEditorStatusItem</code></a></td><td><code>MawyEditorStatusItem</code>, <code>MawyEditorStatusOption</code></td></tr><tr><td><a href="./types/viewer-toolbar-item"><code>MawyViewerToolbarItem</code></a></td><td><code>MawyViewerToolbarItem</code>, <code>MawyViewerToolbarOption</code></td></tr><tr><td><a href="./types/frame">Frame</a></td><td><code>MawyFrame</code>, <code>MawyToolbarPlacement</code></td></tr><tr><td><a href="./types/color-scheme"><code>MawyColorScheme</code></a></td><td><code>MawyColorScheme</code></td></tr><tr><td><a href="./types/locale"><code>MawyLocale</code></a></td><td><code>MawyLocale</code></td></tr><tr><td><a href="./types/parse-options"><code>MawyParseOptions</code></a></td><td><code>MawyParseOptions</code></td></tr><tr><td><a href="./types/md-document"><code>MdDocument</code></a></td><td><code>MdDocument</code> and every node type under it</td></tr><tr><td><a href="./types/html-policy"><code>MawyHtmlPolicy</code></a></td><td><code>MawyHtmlPolicy</code></td></tr><tr><td><a href="./types/link-target">Links</a></td><td><code>MawyLinkTarget</code>, <code>MawyLinkRel</code></td></tr><tr><td><a href="./types/url-resolver"><code>MawyUrlResolver</code></a></td><td><code>MawyUrlResolver</code>, <code>MawyUrlKind</code></td></tr><tr><td><a href="./types/typography"><code>MawyTypography</code></a></td><td><code>MawyTypography</code></td></tr><tr><td><a href="./types/font-family"><code>MawyFontFamily</code></a></td><td><code>MawyFontFamily</code></td></tr><tr><td><a href="./types/font"><code>MawyFont</code></a></td><td><code>MawyFont</code>, <code>MAWY_SYSTEM_FONTS</code>, <code>MAWY_WEB_FONTS</code></td></tr><tr><td><a href="./types/measure"><code>MawyMeasure</code></a></td><td><code>MawyMeasure</code></td></tr><tr><td><a href="./types/directive-kind"><code>MawyDirectiveKind</code></a></td><td><code>MawyDirectiveKind</code></td></tr><tr><td><a href="./types/directives">Directives</a></td><td><code>MawyDirectives</code>, <code>MawyDirectiveProps</code></td></tr><tr><td><a href="./types/highlighter"><code>MawyHighlighter</code></a></td><td><code>MawyHighlighter</code>, <code>MawyHighlight</code>, <code>MawyCodeToken</code>, <code>MawyCodeTokenKind</code></td></tr><tr><td><a href="./types/image">Images</a></td><td><code>MawyImageProps</code>, <code>MawyImageUpload</code>, <code>MawyImageSource</code></td></tr><tr><td><a href="./types/range"><code>MawyRange</code></a></td><td><code>MawyRange</code></td></tr></tbody></table><p>They are also exported from <code>mawy-react/types</code>, so an application can name one in its own props without importing a component to get at it.</p></div><div class="mawy-fw" data-fw="flutter"><table tabindex="0"><thead><tr><th>Page</th><th>What it covers</th></tr></thead><tbody><tr><td><a href="./types/editor-mode">Editor modes</a></td><td><code>MawyEditorMode</code>, <code>kMawyEditorModes</code></td></tr><tr><td><a href="./types/editor-toolbar-item"><code>MawyEditorToolbarItem</code></a></td><td><code>MawyEditorToolbarItem</code>, <code>kMawyEditorToolbar</code></td></tr><tr><td><a href="./types/editor-status-item"><code>MawyEditorStatusItem</code></a></td><td><code>MawyEditorStatusItem</code>, <code>kMawyEditorStatus</code></td></tr><tr><td><a href="./types/viewer-toolbar-item"><code>MawyViewerToolbarItem</code></a></td><td><code>MawyViewerToolbarItem</code>, <code>kMawyViewerToolbar</code></td></tr><tr><td><a href="./types/color-scheme"><code>MawyColorScheme</code></a></td><td><code>MawyColorScheme</code></td></tr><tr><td><a href="./types/locale"><code>MawyLocale</code></a></td><td><code>MawyLocale</code></td></tr><tr><td><a href="./types/parse-options"><code>MawyParseOptions</code></a></td><td><code>MawyParseOptions</code></td></tr><tr><td><a href="./types/md-document"><code>MdDocument</code></a></td><td><code>MdDocument</code> and every node class under it</td></tr><tr><td><a href="./types/url-resolver"><code>MawyUrlResolver</code></a></td><td><code>MawyUrlResolver</code>, <code>MawyUrlKind</code></td></tr><tr><td><a href="./types/typography"><code>MawyTypography</code></a></td><td><code>MawyTypography</code></td></tr><tr><td><a href="./types/font-family"><code>MawyFontFamily</code></a></td><td><code>MawyFontFamily</code></td></tr><tr><td><a href="./types/measure"><code>MawyMeasure</code></a></td><td><code>MawyMeasure</code>, <code>MawyMeasureWidth</code></td></tr><tr><td><a href="./types/directive-kind"><code>MawyDirectiveKind</code></a></td><td><code>MawyDirectiveKind</code></td></tr><tr><td><a href="./types/directives">Directives</a></td><td><code>MawyDirective</code>, <code>MawyDirectiveBuilder</code></td></tr><tr><td><a href="./types/highlighter"><code>MawyHighlighter</code></a></td><td><code>MawyHighlighter</code>, <code>MawyCodeToken</code>, <code>MawyCodeTokenKind</code></td></tr><tr><td><a href="./types/image">Images</a></td><td><code>MawyImage</code>, <code>MawyImageBuilder</code></td></tr><tr><td><a href="./types/viewer-anchors"><code>MawyViewerAnchors</code></a></td><td><code>MawyViewerAnchors</code></td></tr></tbody></table><p><code>package:mawy/mawy.dart</code> is this package&#39;s entire public surface. One import covers all of it.</p></div><h2 id="functions" tabindex="-1">Functions <a class="header-anchor" href="#functions" aria-label="Permalink to &quot;Functions&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Page</th><th>What it is</th></tr></thead><tbody><tr><td><a href="./functions/parse-markdown"><code>parseMarkdown</code></a></td><td>Reads a string as Markdown, the way the viewer does.</td></tr><tr><td><a href="./functions/slugify"><code>slugify</code></a></td><td>A heading&#39;s anchor, in the spelling GitHub uses.</td></tr><tr><td><a href="./functions/mawy-highlighter"><code>mawyHighlighter</code></a></td><td>The syntax highlighter this library ships.</td></tr><tr><td><a href="./functions/find">Finding text</a></td><td>The arithmetic behind the find bar.</td></tr></tbody></table><h2 id="theming" tabindex="-1">Theming <a class="header-anchor" href="#theming" aria-label="Permalink to &quot;Theming&quot;">​</a></h2><p><a href="./theming">Theming</a> is every colour, radius and duration the library draws with, and the whole of what an application may change.</p><div class="mawy-fw" data-fw="flutter"><p>The editor also exports the arithmetic its formatting commands are made of — <code>MawyCommand</code>, <code>runCommand</code>, <code>commandActive</code>, <code>continueList</code>, <code>indent</code> and the <code>EditState</code> they work on. They are there for an application driving the editor from a toolbar of its own, and they are the same functions under the same names as the React package&#39;s internals.</p></div>',14)])])}const l=t(r,[["render",c]]);export{p as __pageData,l as default};
